Framework not specified. Showing vanilla JS + React. Both cancel stale in-flight requests too, so out-of-order responses can't overwrite newer results.

## Vanilla JS

```js
function debounce(fn, delay = 300) {
  let timer;
  return (...args) => {
    clearTimeout(timer);
    timer = setTimeout(() => fn(...args), delay);
  };
}

const input = document.querySelector('#search');
const results = document.querySelector('#results');
let controller;

async function search(query) {
  controller?.abort();                 // cancel previous request
  if (!query.trim()) { results.innerHTML = ''; return; }

  controller = new AbortController();
  try {
    const res = await fetch(`/api/search?q=${encodeURIComponent(query)}`, {
      signal: controller.signal,
    });
    const data = await res.json();
    results.innerHTML = data.map(d => `<li>${d.name}</li>`).join('');
  } catch (err) {
    if (err.name !== 'AbortError') console.error(err);
  }
}

input.addEventListener('input', debounce(e => search(e.target.value), 300));
```

## React

```jsx
import { useEffect, useState } from 'react';

function useDebounce(value, delay = 300) {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const t = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(t);
  }, [value, delay]);
  return debounced;
}

export function Search() {
  const [query, setQuery] = useState('');
  const [results, setResults] = useState([]);
  const debouncedQuery = useDebounce(query, 300);

  useEffect(() => {
    if (!debouncedQuery.trim()) { setResults([]); return; }

    const controller = new AbortController();
    fetch(`/api/search?q=${encodeURIComponent(debouncedQuery)}`, {
      signal: controller.signal,
    })
      .then(r => r.json())
      .then(setResults)
      .catch(err => { if (err.name !== 'AbortError') console.error(err); });

    return () => controller.abort();   // abort when query changes/unmount
  }, [debouncedQuery]);

  return (
    <>
      <input value={query} onChange={e => setQuery(e.target.value)} />
      <ul>{results.map(r => <li key={r.id}>{r.name}</li>)}</ul>
    </>
  );
}
```

Notes:
- Input stays responsive. Only API call is delayed.
- Delay of 250–400ms is typical.
- In the vanilla version, `d.name` goes into `innerHTML` unescaped. That is an XSS risk if data is untrusted. Use `textContent` or escape it.
- Without `AbortController`, a slow response for "ab" could arrive after "abc" and show wrong results.
